\begin{definition}
			\label{def:epihoro}
			Consider a nonempty subset $C$ of $X$ and a real-valued function $f\from C \to \R$.
			A \textit{Busemann subgradient} of $f$ at a point $x\in C$ is an element $[\xi,s] \in CX^\infty$
			such that $x$ minimizes $y\mapsto f(y) - \ip{y,[\xi,s]}$ over $C$. The function $f$ is \textit{Busemann subdifferentiable} if it has a Busemann subgradient at every point in $C$.

	\end{definition}

\begin{equation}
	\label{eqn:busesub}
	f(y) \geq f(x) + sb_{x,\xi}(y) \text{ for all } y\in C,
\end{equation}
a version of the subgradient inequality in Hadamard space.

