				%\For{$i=0,1,\dots,m-1$}
				\State $[\xi_{k},s_{k}] \leftarrow \texttt{Busemann}(f_{i(k)}, x^{k})$
				\State $x^{k+1} \leftarrow P_C\left(r_{x_{k},\xi_{k}}\left(s_{k}t_k\right)\right)$
				%\EndFor
				%\State $x^{k+1} \leftarrow x^{k,m}$
				\EndFor 		
				\end{algorithmic}
\label{alg:stochsub}
		\end{algorithm}

