\begin{theorem}
			\label{thm:subgrad}
Given a Hadamard space $X$ and $C \seq X$, suppose that the function $f\from C\to \R$ is geodesically convex, with a Busemann subgradient $[\xi,s]$ at $x\in C$. 
			Let $r$ be a ray issuing from $x$ with direction $\xi$.
			Extend $r$ to a geodesic line
			$\tilde{r}\from \R\to X$ and define a new ray $r_-\from \R_+\to X$ by $r_-(t) = \tilde{r}(-t)$.
			Then $([r_-],s) \in \p f(x)$.	
		\end{theorem}

\begin{proof}
			By definition of the scalar product on $T_xX$, the subgradient inequality we wish to prove is
			\[s d(x,y)\cos\angle(r_-,\gamma_y) + f(x)\leq f(y) \text{ for all } y\in X.\]
			Busemann subdifferentiability of $f$ implies, by (\ref{eqn:busesub}), 
			\[s b_r(y) + f(x) \leq f(y) \text{ for all } y\in X.\]
			Thus it is enough to prove (the case $s = 0$ being trivial):
			\begin{equation}
				\label{eqn:desired}
				b_r(y) \geq d(x,y)\cos\angle(r_-,\gamma_y) \text{ for all } y\in X.
			\end{equation}
			We proceed in two steps, first proving 
			$\cos\angle(r_-,\gamma_y) \leq -\cos\angle(r,\gamma_y)$ $(*)$.
			Using the triangle inequality for angles we find:
			\[\pi = \angle(r,r_-) \leq \angle(r_-,\gamma_y) + \angle(r,\gamma_y).\]
			Hence $\pi - \angle(r,\gamma_y)\leq \angle(r_-,\gamma_y)$, and taking the cosine reverses the inequality: 
\begin{equation} \label{star}
\cos\angle(r_-,\gamma_y) \leq \cos(\pi - \angle(r,\gamma_y)) = -\cos\angle(r,\gamma_y).
\end{equation}

			We next prove 
\begin{equation} \label{starstar}
b_r(y) \geq -d(x,y)\cos\angle(r,\gamma_y).
\end{equation}
			By the law of cosines we have:
			\[d(r(t),y)^2 \geq d(x,r(t))^2 + d(x,y)^2 - 2d(x,r(t))d(x,y)\cos\angle(r,\gamma_y).\]
			Rearrangement leads to
			\begin{equation}
				\label{eqn:ineqprelim}
				\frac{d(r(t),y)^2 - t^2}{2t} \geq \frac{d(x,y)^2}{2t} - d(x,y)\cos\angle(r,\gamma_y).
		\end{equation}
		The lefthand side of \eqref{eqn:ineqprelim} simplifies in the limit because $t\mapsto d(r(t),y)-t$ is bounded:
			\begin{align}
				\label{eqn:quadraticbuse}
			\lim_{t\to \infty}\frac{d(r(t),y)^2 - t^2}{2t} &= 
			\lim_{t\to \infty}(d(r(t),y)-t)\lim_{t\to \infty}\frac{d(r(t),y) +t}{2t} \nonumber\\
			&= b_r(y)\lim_{t\to \infty}\left(\frac{d(r(t),y)-t}{2t} + 1 \right)  \nonumber \\
			&= b_r(y).
	\end{align}
	Using \eqref{eqn:quadraticbuse} and sending $t\to \infty$ in (\ref{eqn:ineqprelim}) yields 
	(\ref{starstar}).
			Combining (\ref{star}) and (\ref{starstar}) gives
			\[d(x,y)\cos\angle(r_-,\gamma_y) \leq -d(x,y)\cos\angle(r,\gamma_y) \leq b_r(y).\]
			This proves (\ref{eqn:desired}).
		\end{proof}

